// Execute actual application, campaign controller, state/rules and Store bodies.
// Only boot/DOM/storage are isolated; injected hooks count calls or delay the
// actual provider. Native browser/Web Locks coverage lives in the browser suite.
const harnessURL=new URL('./app-harness.mjs',import.meta.url),storageURL=new URL('./deposit-save-harness.mjs',import.meta.url);
const app=await readFile(new URL('../js/app.mjs',import.meta.url),'utf8');
const notesDecisions=JSON.parse(await readFile(new URL('../rules/decisions.json',import.meta.url),'utf8'));
const marker='store=new Store(receiveCampaign,',roleStart=app.indexOf(marker);assert.ok(roleStart>=0);
const roleCallback=app.slice(roleStart+marker.length).split(');try{state=store.read();}')[0];
const absolutize=(source,url)=>source.replaceAll('import.meta.url',JSON.stringify(url.href)).replace(/from '(\.[^']+)'/g,(_all,path)=>'from '+JSON.stringify(new URL(path,url).href));
function replace(source,from,to){assert.ok(source.includes(from),'Actual harness boundary '+from);return source.replace(from,to);}
let hs=absolutize(await readFile(harnessURL,'utf8'),harnessURL);
hs=replace(hs,'globalThis.api={setStore','globalThis.api={setDecisions(value){decisions=value;},get snapshotId(){return snapshotId;},get tab(){return tab;},get selectedSet(){return selected;},get saleQuotes(){return saleQuotes;},get saleTaxDice(){return saleTaxDice;},completeContactSearchWrite:(...args)=>completeContactSearchWrite(...args),roleChange:'+roleCallback+',setStore');
hs=replace(hs,'calls.quotes++;return bindings.R.quote','calls.quotes++;calls.onQuote?.();return bindings.R.quote');
hs=replace(hs,'priceDice:0','priceDice:0,markets:0,marketDice:0,rolls:0');
hs=replace(hs,'roll:n=>({dice:Array(n).fill(3),total:n*3})','roll:n=>{calls.rolls++;return bindings.R.roll(n,()=>3);},market(...args){calls.markets++;return bindings.R.market(...args,()=>{calls.marketDice++;return 3;});}');
const hm='data:text/javascript;base64,'+Buffer.from(hs).toString('base64');
let ss=absolutize(await readFile(storageURL,'utf8'),storageURL);ss=replace(ss,JSON.stringify(harnessURL.href),JSON.stringify(hm));
const {depositHarness}=await import('data:text/javascript;base64,'+Buffer.from(ss).toString('base64'));
const success=/^(?:supplier|buyer) search: .+ saved\.$|^Buyer found\./i;
function fixture({illegal=false,selected=false,hours=0}={}){
 const s=campaign();s.worlds[s.actual].uwp='A788879-C';s.hours=hours;s.bank='1000000';s.settings={...s.settings,tax:true,profit:75};
 s.ship.accommodation={rooms:{low:0,middle:4,high:0},passengers:{low:0,middle:0,high:0},crew:{low:0,middle:4,high:0},occupiedLowBerths:0,luggageTons:'0'};s.ship.lifeSupport={capacityHours:672,remainingHours:672,elapsedHours:0};
 s.lots=[{id:'cargo',commodity:illegal?'61':'11',description:'Synthetic cargo',quantity:'3',basis:'30001',goodsValue:'27001',illegal,world:s.actual,hours:0}];return S.validate(s);
}
function setup(saved=fixture()){
 const h=depositHarness(saved,{setTimeout:()=>0,clearTimeout(){}}),form=h.dom.ids.get('modal-form'),query=form.querySelectorAll;
 form.querySelectorAll=selector=>selector==='input,select,textarea,button'?[...h.dom.fields().values(),...modalButtons(h),h.dom.ids.get('modal-submit'),h.dom.ids.get('modal-cancel')]:query(selector);
 h.api.setDecisions(notesDecisions);h.store.onRole=(editable,text)=>{h.roles.push([editable,text]);h.hooks.onRole?.(editable,text);h.api.roleChange(editable,text);};return h;
}
function modalButtons(h){return [...body(h).matchAll(/<button\b([^>]*)>/g)].map(m=>element(attrs(m[1])));}
async function prepare(h,kind='supplier',edits={}){h.api.searchDialog(kind);h.fill({party:'Synthetic '+kind,method:'online',dice:12,duration:1,...edits});await h.submit();assert.equal(ui(h).modalTitle,'Review '+kind+' search');assert.equal(ui(h).modalError,'');}
const count=h=>({markets:h.calls.markets,marketDice:h.calls.marketDice,rolls:h.calls.rolls,quotes:h.calls.quotes,priceDice:h.calls.priceDice});
const body=h=>h.dom.ids.get('modal-body').innerHTML;
const display=h=>({summary:h.dom.ids.get('summary').innerHTML,main:h.dom.ids.get('main').innerHTML});
const submitEvent=h=>({preventDefault(){},currentTarget:h.dom.ids.get('modal-form')});
function noSuccess(h){assert.doesNotMatch(ui(h).message,success);}
function terminal(h){assert.equal(h.store.reloadRequired,true);assert.equal(h.store.editable,false);assert.equal(h.dom.ids.get('takeover').disabled,true);assert.match(h.dom.ids.get('save-status').textContent,/reload/i);noSuccess(h);if(ui(h).modalOpen){assert.equal(ui(h).submitDisabled,true);assert.match(ui(h).modalError,/reload/i);}}
function canonical(state){const ids=new Map();return JSON.parse(JSON.stringify(state,(_key,value)=>{if(typeof value==='string'&&/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/i.test(value)){if(!ids.has(value))ids.set(value,'generated-'+ids.size);return ids.get(value);}return value;}));}
async function pending(t,{h=setup(),kind='supplier',edits={}}={}){
 const before=structuredClone(h.api.state),raw=h.bytes();await prepare(h,kind,edits);
 const counts=count(h),selection=h.api.selected,session=h.api.modalSession,review=body(h),visible=display(h),snapshotId=h.api.snapshotId,tab=h.api.tab,gate=serviceSaveGate(h.store),detached=h.dom.ids.get('modal-form').onsubmit,operation=h.submit();await flush();
 assert.equal(gate.entries.length,1,'One actual contact-search transition reached the delayed Store');
 t.after(async()=>{for(const e of gate.entries)if(!e.settled)e.fulfill();await operation;gate.restore();});return {h,before,raw,counts,selection,session,review,visible,snapshotId,tab,gate,detached,operation};
}
function dispatch(h,name,arg=''){const b={disabled:false,dataset:{action:name,arg},closest:selector=>selector==='[data-action]'?b:null};h.dom.dispatch('click',b,{preventDefault(){}});return b;}

