  const gate=serviceSaveGate(h.store),operation=h.submit();gate.entries[0].write();if(releaseWhen==='settled'){gate.entries[0].fulfill();await operation;}const visible=display(h),view=h.api.view,session=h.api.modalSession,counts=count(h);release(false);await flush();same(display(h),visible);assert.equal(h.api.view,view);assert.equal(h.api.modalSession,session);same(count(h),counts);if(releaseWhen==='pending'){gate.entries[0].fulfill();await operation;}assert.equal(h.counters.writes,1);assert.equal(gate.entries.length,1);gate.restore();dispatch(h,'tab','History');await flush();assert.match(h.dom.ids.get('main').innerHTML,/Campaign history/);
